"""Inferred utility leaves, drawn from the docket's capsules and fine rules."""
from write_elements import write,K
import sys,json

def author(k):
 if k=='delta':write(k,'delta','''/* Inferred from replica06 capsules and replica15 triangular sequence arrows. */
ROOT{container-type:size;container-name:od-delta;display:flex;align-items:center;justify-content:center;gap:var(--pad);min-width:0;min-height:0;color:var(--ink)}ROOT>.from,ROOT>.to{display:flex;align-items:center;justify-content:center;max-width:40%;padding:var(--gap-sm) var(--pad);border-radius:999px;font-size:clamp(var(--type-18),calc(4cqw),var(--type-30));font-weight:var(--body-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track);overflow-wrap:anywhere;text-align:center}ROOT>.from{background:var(--n-1);color:var(--n-7)}ROOT>.to{background:var(--a1-1-soft);color:var(--a1-7)}ROOT::before{content:"";order:1;flex:none;width:30px;height:18px;background:var(--n-4);clip-path:polygon(0 35%,60% 35%,60% 0,100% 50%,60% 100%,60% 65%,0 65%)}ROOT>.from{order:0}ROOT>.to{order:2}@container od-delta (max-width:450px){ROOT>.from,ROOT>.to{padding:var(--gap-sm);font-size:var(--type-18)}ROOT::before{width:20px;height:14px}}
''','Two compact capsules express the former and revised figures. A single arrow owned by the whole delta uses the triangular vocabulary of replica15; the revised value takes the accent text role.',[('approval-time','4x2','<div class="delta" DATA><span class="from">3.8일</span><span class="to">2.4일</span></div>'),('queue-count','4x3','<div class="delta" DATA><span class="from">대기 128건</span><span class="to">대기 76건</span></div>')])
 elif k=='gauge':write(k,'meter','''/* Inferred from replica06 long capsules and replica17 bare number labels. */
ROOT{container-type:size;container-name:od-meter;position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto 14px;align-content:center;gap:var(--gap-sm);min-width:0;min-height:0;padding:0 2%;color:var(--ink)}ROOT>.name,ROOT>.fig{margin:0;grid-row:1;align-self:end;font-size:clamp(var(--type-14),calc(2cqw),var(--type-20));font-weight:var(--body-weight);line-height:var(--name-line);letter-spacing:var(--body-track);overflow-wrap:anywhere}ROOT>.fig{grid-column:2;font-weight:var(--figure-weight);font-size:clamp(var(--type-18),calc(3cqw),var(--type-30))}ROOT::before,ROOT::after{content:"";grid-column:1 / -1;grid-row:2;border-radius:999px;min-height:0}ROOT::before{background:var(--n-2)}ROOT::after{background:var(--a1);width:calc(clamp(0,var(--v),100)*1%)}@container od-meter (max-height:90px){ROOT>.name{font-size:var(--type-14)}ROOT>.fig{font-size:var(--type-20)}}
''','A filled capsule track sits below an open name-and-figure pair. Its fourteen-pixel band extends the quiet conclusion capsule of replica06 without adding a card surface.',[('handoff','4x2','<div class="meter" DATA style="--v:73"><p class="name">이관 기록 점검률</p><p class="fig">73%</p></div>'),('stack-three','6x3','<div class="stack" style="grid-column:1 / span 12;grid-row:1 / span 6">'+''.join('<div class="meter" data-el="onboard-docket-gauge" style="--v:'+str(v)+'"><p class="name">'+n+'</p><p class="fig">'+str(v)+'%</p></div>'for n,v in [('접수 분류 승인',86),('담당 조직 배정',64),('후속 조치 대조',41)])+'</div>')])
 elif k=='legend':write(k,'legend','''/* Inferred from replica02 numbered circles and replica17 restrained captions. */
ROOT{container-type:size;display:flex;align-items:center;justify-content:center;align-content:center;flex-wrap:wrap;gap:var(--gap-sm) var(--pad);min-width:0;min-height:0}ROOT>.key{display:flex;align-items:center;gap:calc(var(--gap-sm)/2);max-width:100%;font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink);overflow-wrap:anywhere}ROOT>.key::before{content:"";width:12px;height:12px;border-radius:50%;background:var(--a1);flex:none}ROOT>.key.tone-2::before{background:var(--a2)}ROOT>.key.tone-3::before{background:var(--a3)}ROOT>.key.tone-4::before{background:var(--a4)}ROOT>.key.tone-5::before{background:var(--n-5)}
''','Small circular keys use the numbered-circle vocabulary without its number. Open captions and wrapping spacing keep the legend independent of the plotted series.',[('channels','4x2','<div class="legend" DATA><span class="key tone-1">상담 접수</span><span class="key tone-2">운영 이관</span><span class="key tone-3">승인 검토</span></div>'),('five-long','6x3','<div class="legend" DATA>'+''.join('<span class="key tone-'+str(i+1)+'">'+n+'</span>'for i,n in enumerate(['접수 채널 분류 결과','담당 조직의 이관 대기','예외 요청 검토 현황','수정 배포 승인 내역','후속 품질 점검']))+'</div>')])
 elif k=='logo-group':write(k,'logos','''/* Inferred from replica18 plain media fields and replica02 generous two-column spacing. */
ROOT{container-type:size;container-name:od-logos;display:grid;grid-template-columns:repeat(12,minmax(0,1fr));align-content:center;gap:var(--gap);min-width:0;min-height:0;padding:2%}ROOT>.seat{grid-column:span 4;justify-self:center;inline-size:min(100%,176px);aspect-ratio:1;border-radius:var(--radius-sm);border:var(--stroke) solid var(--n-3);background:var(--n-1);color:var(--n-7)}ROOT:has(>.seat:nth-child(4):last-child)>.seat{grid-column:span 3}ROOT:has(>.seat:nth-child(2):last-child)>.seat{grid-column:span 6}@container od-logos (max-width:560px){ROOT>.seat,ROOT:has(>.seat:nth-child(4):last-child)>.seat{grid-column:span 6;inline-size:min(100%,36cqh,130px)}}
''','Quiet, square logo placements use the thin edge of replica18 and the measured round corner of the docket. Equal members align in a row and form two columns at compact widths.',[('three-partners','6x3','<div class="logos" DATA>'+''.join('<div class="seat logo" data-ph="'+str(i)+'"></div>'for i in range(1,4))+'</div>'),('four-partners','4x4','<div class="logos" DATA>'+''.join('<div class="seat logo" data-ph="'+str(i)+'"></div>'for i in range(1,5))+'</div>')])
 elif k=='table':
  css='''/* Inferred from replica16 fine list rules and replica18 split-title gray surfaces. */
ROOT{container-type:size;container-name:od-table;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;padding:1%}ROOT>.table{width:100%;border-collapse:collapse;table-layout:fixed;border:var(--stroke) solid var(--n-4);font-size:clamp(var(--type-12),calc(1.6cqw),var(--type-18));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink)}ROOT>.table th,ROOT>.table td{padding:var(--gap-sm);text-align:left;border-bottom:var(--stroke) solid var(--n-4);vertical-align:middle;overflow-wrap:anywhere}ROOT>.table th{background:var(--n-2);font-weight:var(--name-weight)}ROOT>.table tbody tr:nth-child(even){background:var(--n-1)}ROOT>.table .pick{background:var(--a1-1-soft);color:var(--a1-7)}ROOT>.table .num{text-align:right;font-variant-numeric:tabular-nums}@container od-table (max-width:600px){ROOT>.table th,ROOT>.table td{padding:calc(var(--gap-sm)/2);font-size:var(--type-12)}}@container od-table (max-height:240px){ROOT>.table th,ROOT>.table td{padding:calc(var(--gap-sm)/2)}}
'''
  def table(long=False):
   heads=['점검 대상','담당 조직','처리 건수','대기 건수'] if long else ['점검 항목','검토 상태','처리 건수']
   rows=[['이관 기록의 승인 근거','운영 지원','287','34'],['채널별 예외 요청','품질 관리','162','21'],['배포 전 변경 내역','서비스 기획','94','8'],['후속 문의의 응답 기준','고객 상담','208','17']]
   return '<div class="tablebox" DATA><table class="table"><thead><tr>'+''.join('<th>'+x+'</th>'for x in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td'+(' class="num pick"'if j==len(heads)-1 else '')+'>'+v+'</td>'for j,v in enumerate(row if long else [row[0],['승인 완료','보완 요청','검토 진행','승인 완료'][i],row[2]]))+'</tr>'for i,row in enumerate(rows))+'</tbody></table></div>'
  write(k,'tablebox',css,'A neutral header band and alternating quiet rows translate the ruled lists of replica16 into a proper table. The selected column takes a pale accent surface and deep accent text; numeric cells align to the right.',[('review-three','6x3',table()),('review-four-long','8x4',table(True))])
 elif k=='code':
  write(k,'code','''/* Inferred from replica18 split title bays and replica16 ruled lists; no source code panel exists. */
ROOT{container-type:size;container-name:od-code;display:flex;flex-direction:column;justify-content:center;min-width:0;min-height:0;padding:var(--pad);border-radius:var(--radius);background:var(--n-1);color:var(--ink)}ROOT>.name{margin:0 0 var(--gap-sm);padding-bottom:var(--gap-sm);border-bottom:var(--stroke) solid var(--n-4);font-family:var(--font-body);font-size:var(--type-16);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track)}ROOT>.lines{counter-reset:od-code}ROOT>.lines>p{position:relative;margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--onboard-docket-font-code);font-size:clamp(var(--type-12),calc(1.5cqw),var(--type-16));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);counter-increment:od-code}ROOT.numbered>.lines>p{padding-left:3em}ROOT.numbered>.lines>p::before{content:counter(od-code);position:absolute;left:0;width:2em;text-align:right;color:var(--n-7)}ROOT .k{color:var(--a1-7);font-weight:var(--name-weight)}ROOT .s{color:var(--a2-7)}ROOT .c{color:var(--n-7)}ROOT .n{color:var(--a3-7)}@container od-code (max-width:450px){ROOT>.name{font-size:var(--type-14)}ROOT>.lines>p{font-size:var(--type-12)}}@container od-code (max-height:200px){ROOT>.name{display:none}}
''','A quiet paper field has a ruled filename bay and an open monospaced listing. Deep palette roles distinguish tokens while optional line numbers follow the docket’s ordered-list treatment.',[('handoff-policy','6x3','<div class="code numbered" DATA><p class="name">handoff-policy.json</p><div class="lines"><p>{</p><p>  <span class="s">"owner"</span>: <span class="s">"운영 지원"</span>,</p><p>  <span class="s">"reviewDays"</span>: <span class="n">3</span>,</p><p>  <span class="s">"approvalRequired"</span>: <span class="k">true</span></p><p>}</p></div></div>'),('review-rule','4x3','<div class="code" DATA><p class="name">review_rule.py</p><div class="lines"><p><span class="k">def</span> approve(record):</p><p>  <span class="c"># 승인 이력과 담당 조직 대조</span></p><p>  <span class="k">return</span> record.owner != <span class="s">""</span></p></div></div>')])
  f=K/'elements/code/element.json';j=json.loads(f.read_text());j['tokenDefaults']['--onboard-docket-font-code']="'Nanum Gothic Coding'";f.write_text(json.dumps(j,indent=2))
 else:raise SystemExit(k)
if __name__=='__main__':author(sys.argv[1])
